}

function materializeDurationFieldsAt(
  value: unknown,
  key: string | undefined,
): unknown {
  if (value === null || value === undefined) return value;
  if (typeof value === "number") {
    if (key !== undefined && durationFieldNames.has(key)) {
      return durationFromMs(value);
    }
    return value;
  }
  if (typeof value !== "object") return value;
  if (isDurationValue(value)) return value;
  if (Array.isArray(value)) {
    let copy: unknown[] | undefined;
    for (let index = 0; index < value.length; index++) {
      const item = value[index];
      const next = materializeDurationFieldsAt(item, undefined);
      if (next !== item) {
        copy ??= value.slice();
        copy[index] = next;
      }
    }
    return copy ?? value;
  }
  const record = value as Record<string, unknown>;
  let copy: Record<string, unknown> | undefined;
  for (const [childKey, child] of Object.entries(record)) {
    const next = materializeDurationFieldsAt(child, childKey);
    if (next !== child) {
      copy ??= { ...record };
      copy[childKey] = next;
    }
  }
  return copy ?? value;
}

